mapper.insert:
INSERT INTO travel_plan_invitations (
    travel_plan_id, created_by_user_id, token_hash, status
) VALUES (
    #{travelPlanId}, #{createdByUserId}, #{tokenHash}, #{status}
)

mapper.update:
UPDATE travel_plan_invitations
SET status = #{toStatus},
    invalidated_at = CURRENT_TIMESTAMP,
    updated_at = CURRENT_TIMESTAMP
WHERE travel_plan_id = #{travelPlanId}
  AND status = #{fromStatus}

mapper.select:
SELECT id, travel_plan_id, created_by_user_id, token_hash, status,
       invalidated_at, created_at, updated_at
FROM travel_plan_invitations
WHERE token_hash = #{tokenHash}
  AND status = #{status}
